The aim is to find a model $\mathcal{B}_\Omega$ in the model class such that
\begin{enumerate}
 \item $\mathcal{B}_\Omega$ is unfalsified by $\Omega$, i.e. \ $\Omega \subseteq \mathcal{B}_\Omega$.
 \item $\mathcal{B}_\Omega$ is most powerful, i.e.\ for every behavior $\mathcal{B}$ with
$\Omega \subseteq \mathcal{B}$, it follows that $\mathcal{B}_\Omega \subseteq \mathcal{B}$.
\end{enumerate}

For this, we have to show that 
\begin{enumerate}
 \item $ (o_1 \cdot o_2) \bullet p = o_1 \bullet ( o_2 \bullet p ) \;\;\;\; $ for all $o_1, o_2 \in O$ and $p \in A$ 
 \item $ (o_1 + o_2) \bullet p = o_1 \bullet p +  o_2 \bullet p \;\;\;\; $ for all $o_1, o_2 \in O$ and $p \in A$ 
 \item $ o \bullet (p+q) = o \bullet p + o \bullet q \;\;\;\; $ for all $o \in O$ and $p, q \in A.$ 
\end{enumerate}

Then the 
action of $\partial_i$ is exactly the $\sigma_i$-derivation $\delta_i$, since 
\begin{eqnarray*}
\partial_i [p] = [ \partial_i p] = [ \sigma_i(p) \partial_i + \delta_i(p)] = 
[\delta_i(p)] = [\partial_i \bullet p].
\end{eqnarray*}

Let $p \in A$ and $o \in O$. Then there is the following equivalence
\begin{eqnarray*} 
o \bullet p =0 \;\;\; \mbox{ if and only if } \;\;\; 
o \cdot p \in {}_{O} \langle \partial_1, \dots, \partial_s \rangle.
\end{eqnarray*}

In this section, we suppose $O$ to be the $n$-th Weyl algebra 

\begin{center}
$O = \mathrm{W}_n:= \mathbb{C}[t_1, \dots, t_n][ \partial_1; \mathrm{id}_{ \mathrm{W}_n}, \frac{\partial}{\partial t_1}] 
\cdots [ \partial_n; \mathrm{id}_{ \mathrm{W}_n}, \frac{\partial}{\partial t_n}].$
\end{center}

Define for $\lambda \in \mathbb{C}^n$ the 
$\mathrm{W}_n$-homomorphism
\begin{eqnarray*}
\sigma_{\lambda}: \mathrm{W}_n \rightarrow \mathrm{W}_n, \;\;\; \partial_i \mapsto (\partial_i - \lambda_i), \;\; t_i \mapsto t_i .
\end{eqnarray*}

We claim that for $a \in \mathrm{W}_n$ and $f \in A$
\begin{eqnarray} a \bullet p =0 \;\;\; \mbox{ if and only if } \;\;\; \sigma_{\lambda}(a) \bullet (p \exp_{\lambda})=0.
\end{eqnarray}

For the proof suppose $a= \sum_i c_i t^{\alpha_i} \partial^{\beta_i}$. 

Using the identity 
$(\partial_i - \lambda_i) \bullet (p \exp_{\lambda}) = (\partial_i \bullet p)\exp_{\lambda} $, 
the claim follows by
\begin{eqnarray*}
\sigma_{\lambda}(a) \bullet (p \exp_{\lambda}) 

&=& \sum_i c_i t^{\alpha_i}(\, (\partial_1-\lambda_1)^{{\beta_i}_1} \cdots (\partial_n-\lambda_n)^{{\beta_i}_n}\,) \bullet (p \exp_{\lambda})\\
& = &\sum_i c_i t^{\alpha_i}(\, (\partial_1^{{\beta_i}_1} \cdots \partial_n^{{\beta_i}_n}\,) \bullet p) \, \exp_{\lambda}

= \quad (a\bullet p)\exp_{\lambda} .
\end{eqnarray*}

